// Package regfgen builds synthetic Windows registry hives (REGF) in
// memory, for TEST FIXTURES ONLY.
//
// Tracefall's registry tests need hives whose contents are known exactly
// and that can be regenerated byte-for-byte on any machine. Real hives
// cannot serve that purpose: they are large, they carry real usernames,
// SIDs, installed software and machine names, and they cannot be
// committed to a repository. Every hive produced here is entirely
// invented -- see testdata/native_samples/README.md.
//
// This is a deliberately minimal writer, not a general registry library:
// it emits one hive bin, `lf` subkey lists, and either resident or
// single-cell value data. That is enough to exercise every path in the
// reader (including the ones the reader must REJECT, via the corrupting
// helpers at the bottom of this file) and nothing more.
//
// It intentionally lives outside internal/regf so no production code can
// import a hive writer by accident: Tracefall must never write a hive.
package regfgen

import (
	"encoding/binary"
	"time"
	"unicode/utf16"
)

// Value is one registry value to write.
type Value struct {
	Name string // "" writes the key's default value
	Type uint32 // a regf.Reg* code
	Data []byte
}

// StringValue builds a REG_SZ value, encoding s as NUL-terminated
// UTF-16LE exactly as Windows stores it.
func StringValue(name, s string) Value {
	return Value{Name: name, Type: 1, Data: encodeUTF16(s)}
}

// ExpandStringValue builds a REG_EXPAND_SZ value (e.g. a service
// ImagePath containing %SystemRoot%).
func ExpandStringValue(name, s string) Value {
	return Value{Name: name, Type: 2, Data: encodeUTF16(s)}
}

// MultiStringValue builds a REG_MULTI_SZ value: NUL-separated strings
// terminated by an empty string.
func MultiStringValue(name string, items []string) Value {
	var u []uint16
	for _, s := range items {
		u = append(u, utf16.Encode([]rune(s))...)
		u = append(u, 0)
	}
	u = append(u, 0)
	return Value{Name: name, Type: 7, Data: uint16sToBytes(u)}
}

// DWordValue builds a REG_DWORD value.
func DWordValue(name string, v uint32) Value {
	b := make([]byte, 4)
	binary.LittleEndian.PutUint32(b, v)
	return Value{Name: name, Type: 4, Data: b}
}

// BinaryValue builds a REG_BINARY value.
func BinaryValue(name string, data []byte) Value {
	return Value{Name: name, Type: 3, Data: data}
}

// Key is one key in the synthetic hive.
type Key struct {
	Name      string
	LastWrite time.Time
	Values    []Value
	Subkeys   []*Key
}

// NewKey is a small convenience for building trees inline in a test.
func NewKey(name string, subkeys ...*Key) *Key {
	return &Key{Name: name, Subkeys: subkeys}
}

// WithValues attaches values to a key and returns it, so a tree can be
// written as one expression.
func (k *Key) WithValues(values ...Value) *Key {
	k.Values = append(k.Values, values...)
	return k
}

// WithLastWrite sets a key's last-write timestamp. Tests that assert on
// timeline placement set this explicitly rather than relying on a
// default, so the expected timestamps are visible in the test itself.
func (k *Key) WithLastWrite(t time.Time) *Key {
	k.LastWrite = t
	return k
}

const (
	baseBlockSize  = 512
	hiveBinsOffset = 4096
	hbinHeaderSize = 32
)

type builder struct {
	// bins holds hive bins data: the hbin header followed by cells.
	// Offsets handed out are relative to the start of this slice, which
	// is exactly the convention the format uses.
	bins []byte
}

// alloc writes one cell containing data and returns its hive-relative
// offset. Cell size is stored negative (allocated) and includes the
// 4-byte size field, padded to an 8-byte boundary.
func (b *builder) alloc(data []byte) uint32 {
	size := 4 + len(data)
	if pad := size % 8; pad != 0 {
		size += 8 - pad
	}
	off := uint32(len(b.bins))

	cell := make([]byte, size)
	binary.LittleEndian.PutUint32(cell[0:4], uint32(int32(-size)))
	copy(cell[4:], data)
	b.bins = append(b.bins, cell...)
	return off
}

// writeKey serializes a key and everything beneath it, returning the
// offset of its nk record. Children are written first (post-order) so a
// parent always has real offsets for its subkey list.
func (b *builder) writeKey(k *Key, parentOffset uint32, isRoot bool) uint32 {
	// Values first: the value list needs their offsets.
	var valueOffsets []uint32
	for _, v := range k.Values {
		valueOffsets = append(valueOffsets, b.writeValue(v))
	}
	var valueListOffset uint32 = 0xffffffff
	if len(valueOffsets) > 0 {
		list := make([]byte, 4*len(valueOffsets))
		for i, off := range valueOffsets {
			binary.LittleEndian.PutUint32(list[i*4:], off)
		}
		valueListOffset = b.alloc(list)
	}

	// Reserve this key's nk cell before writing children, so children can
	// record a correct parent offset. The cell is filled in afterwards.
	nameBytes := []byte(k.Name) // ASCII names (KEY_COMP_NAME), as Windows does for ordinary keys
	nkSize := 76 + len(nameBytes)
	if pad := (4 + nkSize) % 8; pad != 0 {
		nkSize += 8 - pad
	}
	nkOffset := b.alloc(make([]byte, nkSize))

	var subkeyOffsets []uint32
	for _, sub := range k.Subkeys {
		subkeyOffsets = append(subkeyOffsets, b.writeKey(sub, nkOffset, false))
	}
	var subkeyListOffset uint32 = 0xffffffff
	if len(subkeyOffsets) > 0 {
		list := make([]byte, 4+8*len(subkeyOffsets))
		copy(list[0:2], "lf")
		binary.LittleEndian.PutUint16(list[2:4], uint16(len(subkeyOffsets)))
		for i, off := range subkeyOffsets {
			binary.LittleEndian.PutUint32(list[4+i*8:], off)
			// Name hash: real hives store one, but no reader is required
			// to verify it and this one does not, so a stable placeholder
			// keeps fixtures byte-reproducible.
			binary.LittleEndian.PutUint32(list[4+i*8+4:], 0)
		}
		subkeyListOffset = b.alloc(list)
	}

	// Now fill in the reserved nk cell.
	nk := b.bins[hiveBinsOffsetOf(nkOffset)+4:]
	copy(nk[0:2], "nk")
	var flags uint16 = 0x0020 // KEY_COMP_NAME: ASCII name
	if isRoot {
		flags |= 0x0004 // KEY_HIVE_ENTRY
	}
	binary.LittleEndian.PutUint16(nk[2:4], flags)
	binary.LittleEndian.PutUint64(nk[4:12], toFileTime(k.LastWrite))
	binary.LittleEndian.PutUint32(nk[16:20], parentOffset)
	binary.LittleEndian.PutUint32(nk[20:24], uint32(len(subkeyOffsets)))
	binary.LittleEndian.PutUint32(nk[28:32], subkeyListOffset)
	binary.LittleEndian.PutUint32(nk[32:36], 0xffffffff) // volatile subkey list
	binary.LittleEndian.PutUint32(nk[36:40], uint32(len(valueOffsets)))
	binary.LittleEndian.PutUint32(nk[40:44], valueListOffset)
	binary.LittleEndian.PutUint32(nk[44:48], 0xffffffff) // security key
	binary.LittleEndian.PutUint32(nk[48:52], 0xffffffff) // class name
	binary.LittleEndian.PutUint16(nk[72:74], uint16(len(nameBytes)))
	copy(nk[76:], nameBytes)
	return nkOffset
}

// hiveBinsOffsetOf converts a hive-relative cell offset into an index
// into the builder's bins slice. They are the same number -- the helper
// exists so the intent is explicit at the call site rather than looking
// like a unit confusion.
func hiveBinsOffsetOf(off uint32) int { return int(off) }

func (b *builder) writeValue(v Value) uint32 {
	nameBytes := []byte(v.Name)

	var dataSize, dataOffset uint32
	switch {
	case len(v.Data) == 0:
		dataSize, dataOffset = 0, 0xffffffff
	case len(v.Data) <= 4:
		// Resident: the data lives in the offset field, flagged by the
		// data size's high bit.
		var buf [4]byte
		copy(buf[:], v.Data)
		dataSize = uint32(len(v.Data)) | 0x80000000
		dataOffset = binary.LittleEndian.Uint32(buf[:])
	default:
		dataSize = uint32(len(v.Data))
		dataOffset = b.alloc(v.Data)
	}

	vk := make([]byte, 20+len(nameBytes))
	copy(vk[0:2], "vk")
	binary.LittleEndian.PutUint16(vk[2:4], uint16(len(nameBytes)))
	binary.LittleEndian.PutUint32(vk[4:8], dataSize)
	binary.LittleEndian.PutUint32(vk[8:12], dataOffset)
	binary.LittleEndian.PutUint32(vk[12:16], v.Type)
	if len(nameBytes) > 0 {
		binary.LittleEndian.PutUint16(vk[16:18], 0x0001) // VALUE_COMP_NAME: ASCII
	}
	copy(vk[20:], nameBytes)
	return b.alloc(vk)
}

// Build serializes a complete hive: base block, one hive bin, and the
// key tree beneath root. embeddedName is written into the base block's
// filename field, which is where a real hive records its own NT path.
func Build(embeddedName string, root *Key) []byte {
	b := &builder{bins: make([]byte, hbinHeaderSize)}
	rootOffset := b.writeKey(root, 0xffffffff, true)

	// A hive bin's size must be a multiple of 4096.
	if pad := len(b.bins) % 4096; pad != 0 {
		b.bins = append(b.bins, make([]byte, 4096-pad)...)
	}
	binsSize := uint32(len(b.bins))

	copy(b.bins[0:4], "hbin")
	binary.LittleEndian.PutUint32(b.bins[4:8], 0) // this bin's offset within bins data
	binary.LittleEndian.PutUint32(b.bins[8:12], binsSize)

	out := make([]byte, hiveBinsOffset+len(b.bins))
	base := out[:baseBlockSize]
	copy(base[0:4], "regf")
	binary.LittleEndian.PutUint32(base[4:8], 1)  // primary sequence
	binary.LittleEndian.PutUint32(base[8:12], 1) // secondary sequence (equal == synchronized)
	binary.LittleEndian.PutUint64(base[12:20], toFileTime(root.LastWrite))
	binary.LittleEndian.PutUint32(base[20:24], 1) // major version
	binary.LittleEndian.PutUint32(base[24:28], 5) // minor version
	binary.LittleEndian.PutUint32(base[28:32], 0) // file type 0 == hive (not a transaction log)
	binary.LittleEndian.PutUint32(base[32:36], 1) // file format: direct memory load
	binary.LittleEndian.PutUint32(base[36:40], rootOffset)
	binary.LittleEndian.PutUint32(base[40:44], binsSize)
	binary.LittleEndian.PutUint32(base[44:48], 1) // clustering factor
	copy(base[48:112], encodeUTF16(embeddedName))
	binary.LittleEndian.PutUint32(base[508:512], xor32(base[:508]))

	copy(out[hiveBinsOffset:], b.bins)
	return out
}

// ---------- deliberately broken fixtures ----------
//
// These produce the malformed inputs the reader must refuse. They are
// generated rather than committed as binary blobs so the exact nature of
// each defect is visible in code.

// Truncate cuts a hive short, simulating the very common case of a hive
// copied while the system was running.
func Truncate(hive []byte, keep int) []byte {
	if keep > len(hive) {
		keep = len(hive)
	}
	out := make([]byte, keep)
	copy(out, hive)
	return out
}

// CorruptSignature replaces the REGF magic, so the file is not a hive at
// all.
func CorruptSignature(hive []byte) []byte {
	out := append([]byte(nil), hive...)
	copy(out[0:4], "XXXX")
	return out
}

// CorruptRootOffset points the root key outside the hive bins data --
// the canonical "never trust an offset from the evidence" case.
func CorruptRootOffset(hive []byte) []byte {
	out := append([]byte(nil), hive...)
	binary.LittleEndian.PutUint32(out[36:40], 0x7fffffff)
	return out
}

// CycleSubkeyList rewrites the root key's subkey list so its first entry
// points back at the root itself, which would loop forever in a reader
// without cycle detection.
func CycleSubkeyList(hive []byte) []byte {
	out := append([]byte(nil), hive...)
	rootOffset := binary.LittleEndian.Uint32(out[36:40])
	nk := hiveBinsOffset + int(rootOffset) + 4
	subkeyList := binary.LittleEndian.Uint32(out[nk+28 : nk+32])
	if subkeyList == 0xffffffff {
		return out
	}
	list := hiveBinsOffset + int(subkeyList) + 4
	binary.LittleEndian.PutUint32(out[list+4:list+8], rootOffset)
	return out
}

// MakeTransactionLog flips the file type so the hive presents as a
// registry transaction log, which carries no usable key tree.
func MakeTransactionLog(hive []byte) []byte {
	out := append([]byte(nil), hive...)
	binary.LittleEndian.PutUint32(out[28:32], 1)
	return out
}

// ---------- helpers ----------

func encodeUTF16(s string) []byte {
	u := utf16.Encode([]rune(s))
	u = append(u, 0) // NUL terminator, as Windows stores REG_SZ
	return uint16sToBytes(u)
}

func uint16sToBytes(u []uint16) []byte {
	b := make([]byte, len(u)*2)
	for i, c := range u {
		binary.LittleEndian.PutUint16(b[i*2:], c)
	}
	return b
}

func toFileTime(t time.Time) uint64 {
	if t.IsZero() {
		return 0
	}
	const epochDelta = 11644473600
	return uint64((t.UTC().Unix()+epochDelta)*10_000_000) + uint64(t.Nanosecond()/100)
}

func xor32(b []byte) uint32 {
	var sum uint32
	for i := 0; i+4 <= len(b); i += 4 {
		sum ^= binary.LittleEndian.Uint32(b[i : i+4])
	}
	// A checksum of 0 or 0xffffffff is stored adjusted, per the format.
	if sum == 0 {
		return 1
	}
	if sum == 0xffffffff {
		return 0xfffffffe
	}
	return sum
}
